import hmac

def _arni_users():
    try:
        users = st.secrets.get("users", {})
        return dict(users)
    except Exception:
        return {}

def _arni_login():
    if st.session_state.get("arni_logged_in", False):
        return True

    st.markdown(f"""
    <style>
    .arni-login-shell{{
        max-width:560px;
        margin:7vh auto 0 auto;
        padding:22px 26px 24px;
        background:#ffffff;
        border:1px solid #dce4ee;
        border-radius:999px;
        box-shadow:0 12px 34px rgba(15,23,42,.10);
    }}
    .arni-login-brand{{
        display:flex;
        align-items:center;
        justify-content:center;
        gap:18px;
    }}
    .arni-login-brand img{{
        width:145px;
        max-width:42%;
        height:auto;
        display:block;
    }}
    .arni-login-divider{{
        width:1px;
        height:76px;
        background:#d9c28c;
        flex:0 0 1px;
    }}
    .arni-login-copy{{text-align:left;}}
    .arni-login-logo{{
        font-size:38px;
        line-height:1;
        font-weight:900;
        color:#b78631;
        letter-spacing:.5px;
    }}
    .arni-login-sub{{
        color:#9a7438;
        font-size:17px;
        margin-top:9px;
    }}
    @media (max-width: 768px){{
        .arni-login-shell{{
            margin:4vh .25rem 0 .25rem;
            padding:18px 16px 20px;
            border-radius:36px;
        }}
        .arni-login-brand{{gap:12px;}}
        .arni-login-brand img{{width:112px;}}
        .arni-login-divider{{height:62px;}}
        .arni-login-logo{{font-size:30px;}}
        .arni-login-sub{{font-size:15px;}}
    }}
    </style>
    <div class="arni-login-shell">
      <div class="arni-login-brand">
        <img src="data:image/png;base64,{ARNI_LOGO_B64}" alt="ARNI logo">
        <div class="arni-login-divider"></div>
        <div class="arni-login-copy">
          <div class="arni-login-logo">ARNI</div>
          <div class="arni-login-sub">Üye Girişi</div>
        </div>
      </div>
    </div>
    """, unsafe_allow_html=True)

    users = _arni_users()
    if not users:
        st.error("Üyelik sistemi henüz ayarlanmadı. Streamlit Secrets bölümüne kullanıcı eklenmeli.")
        st.stop()

    with st.form("arni_login_form", clear_on_submit=False):
        username = st.text_input("Kullanıcı adı", placeholder="Kullanıcı adınızı girin")
        password = st.text_input("Şifre", type="password", placeholder="Şifrenizi girin")
        submitted = st.form_submit_button("Giriş Yap", type="primary", use_container_width=True)

    if submitted:
        expected = users.get(username.strip())
        if expected is not None and hmac.compare_digest(str(expected), str(password)):
            st.session_state["arni_logged_in"] = True
            st.session_state["arni_username"] = username.strip()
            st.rerun()
        else:
            st.error("Kullanıcı adı veya şifre yanlış.")

    st.caption("🔒 ARNI yalnızca yetkili üyeler içindir.")
    return False

if not _arni_login():
    st.stop()


