            st.write(f'Destek **{para}{soru_sonuc["destek"]:,.2f}** · Direnç **{para}{soru_sonuc["direnc"]:,.2f}** · Hedef **{para}{soru_sonuc["hedef"]:,.2f}** · Stop **{para}{soru_sonuc["stop"]:,.2f}**')

